={{
(() => {
  // Lee el cursor correspondiente a la ejecución actual del ciclo.
  const cursorItems = $('Leer cursor SECOP II').all(0, $runIndex);
  const cursor = cursorItems[0]?.json ?? {};

  const rawTimestamp =
    cursor.cursor_timestamp || cursor.sync_from;

  if (!rawTimestamp) {
    throw new Error(
      'No se encontró cursor_timestamp ni sync_from.'
    );
  }

  const timestamp = new Date(rawTimestamp)
    .toISOString()
    .replace('Z', '');

  const processId = String(
    cursor.cursor_process_id || ''
  ).replace(/'/g, "''");

  // Primera sincronización: todavía no existe processId.
  if (!processId) {
    return (
      "fecha_de_publicacion_del IS NOT NULL " +
      "AND fecha_de_ultima_publicaci >= '" +
      timestamp +
      "'"
    );
  }

  // Siguientes lotes: utiliza fecha + identificador.
  return (
    "fecha_de_publicacion_del IS NOT NULL AND (" +
      "fecha_de_ultima_publicaci > '" + timestamp + "'" +
      " OR (" +
        "fecha_de_ultima_publicaci = '" + timestamp + "'" +
        " AND id_del_proceso > '" + processId + "'" +
      ")" +
    ")"
  );
})()
}}

parameters.query:
WITH batch AS (
 SELECT * FROM jsonb_to_recordset($1::jsonb) AS r(cursor_timestamp timestamptz,cursor_process_id text)
) SELECT 'SECOP_II_PROCESSES'::text AS source_code,cursor_timestamp,cursor_process_id,
 jsonb_array_length($1::jsonb) AS batch_count FROM batch
 WHERE cursor_timestamp IS NOT NULL AND NULLIF(cursor_process_id,'') IS NOT NULL
 ORDER BY cursor_timestamp DESC,cursor_process_id COLLATE "C" DESC LIMIT 1;
